import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    last_me, last_op = history[-1]
    prev_me, prev_op = history[-2]
    if last_op == 'D':
        return 'D'
    if n >= 3:
        if history[-2][1] == 'D' and history[-3][1] == 'D':
            return 'D'
    if n >= 10:
        recent = history[-10:]
        opp_c = sum(1 for a, b in recent if b == 'C')
        if opp_c <= 2:
            return 'D'
    if n >= 20:
        opp_d_total = sum(1 for a, b in history if b == 'D')
        if opp_d_total >= n // 2:
            return 'D'
    return 'C'

